head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[util > M > isNull]<br/>전달된 값이 null 또는 undefined 인지 판별하여 결과를 반환합니다.",
    "validation" : [
        "value(필수) 파라미터로 null 여부를 검사할 값을 설정할 수 있어야 합니다.",
        "value 파라미터가 null 또는 undefined 이면 true 를 반환해야 합니다.",
        "value 파라미터가 null 또는 undefined 가 아니면 false 를 반환해야 합니다.",
        "빈 문자열, 0, false 등의 값은 null/undefined 가 아니므로 false 를 반환해야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



scwin.btn_isNull_null_onclick = function () {
    let ret = WebSquare.util.isNull(null);
    wf_body_bottom.getObj("scwin").setReturnValue("isNull(null) : " + ret);
}

scwin.btn_isNull_undefined_onclick = function () {
    let ret = WebSquare.util.isNull(undefined);
    wf_body_bottom.getObj("scwin").setReturnValue("isNull(undefined) : " + ret);
}

scwin.btn_isNull_string_onclick = function () {
    let ret = WebSquare.util.isNull("abc");
    wf_body_bottom.getObj("scwin").setReturnValue("isNull('abc') : " + ret);
}

scwin.btn_isNull_zero_onclick = function () {
    let ret = WebSquare.util.isNull(0);
    wf_body_bottom.getObj("scwin").setReturnValue("isNull(0) : " + ret);
}

scwin.btn_isNull_empty_onclick = function () {
    let ret = WebSquare.util.isNull("");
    wf_body_bottom.getObj("scwin").setReturnValue("isNull('') : " + ret);
}

scwin.btn_isNull_false_onclick = function () {
    let ret = WebSquare.util.isNull(false);
    wf_body_bottom.getObj("scwin").setReturnValue("isNull(false) : " + ret);
}
